H.background();
H.text("Net ionic equation: AgNO3 + NaCl -> AgCl(s)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Drop spectator ions to reveal the net ionic equation", 24, 52, { color: H.colors.sub, size: 13 });
const reveal = Math.max(0, Math.min(1, P.reveal));
const breathe = 0.5 + 0.5 * Math.sin(t * 1.6);
const cx = H.W / 2;
const ions = [
  { name: "Ag+", spec: false, col: H.colors.accent2 },
  { name: "NO3-", spec: true, col: H.colors.sub },
  { name: "Na+", spec: true, col: H.colors.sub },
  { name: "Cl-", spec: false, col: H.colors.good }
];
const baseY = 150;
const slotW = 160;
const startX = cx - slotW * 1.5;
for (let i = 0; i < ions.length; i++) {
  const io = ions[i];
  const x = startX + i * slotW;
  const dy = io.spec ? reveal * 130 : 6 * Math.sin(t * 2 + i);
  const r = 27;
  H.circle(x, baseY + dy, r, { fill: io.col, stroke: H.colors.ink, width: 2 });
  H.text(io.name, x, baseY + dy, { color: H.colors.bg, size: 14, weight: 700, align: "center", baseline: "middle" });
  if (io.spec) H.text("spectator", x, baseY + dy + 46, { color: H.colors.warn, size: 11, align: "center" });
  else H.text("reacts", x, baseY - 46, { color: H.colors.good, size: 11, align: "center" });
}
const py = 370;
const glow = 1 + 0.15 * breathe;
H.rect(cx - 95, py - 36, 190, 72, { fill: H.colors.panel, stroke: H.colors.accent, width: 2, radius: 10 });
H.text("AgCl (s)", cx, py - 4, { color: H.colors.ink, size: 20 * glow, weight: 700, align: "center", baseline: "middle" });
H.text("precipitate forms", cx, py + 22, { color: H.colors.accent, size: 12, align: "center", baseline: "middle" });
H.arrow(startX, baseY + 40, cx - 34, py - 42, { color: H.colors.accent2, width: 2 });
H.arrow(startX + 3 * slotW, baseY + 40, cx + 34, py - 42, { color: H.colors.good, width: 2 });
H.text("Net ionic:  Ag+(aq) + Cl-(aq) -> AgCl(s)", 24, 502, { color: H.colors.accent, size: 15, weight: 700 });
H.text("spectators removed:  " + (reveal * 100).toFixed(0) + "%   (Na+ and NO3- stay in solution)", 24, 526, { color: H.colors.sub, size: 13 });
